/* =========================================================================
 * panel.js —— 頂部浮動選單折疊（桌面版 / 移動版共用）
 * -------------------------------------------------------------------------
 * 面板內容（.global-controls 的子元素）依畫面由上而下排列，
 * 折疊時一律「由下往上」收起，狀態只記錄目前顯示前幾列（0 = 全關）。
 * 操作：
 *   - 點擊切換列：全開 ↔ 全關
 *   - 拖曳切換列：面板高度跟著手指 / 滑鼠移動，放開後吸附到最近的列邊界
 *   - 頁面往下捲動：自動全關；往上捲動：恢復成使用者設定的列數
 *     （自動收合不會覆蓋使用者的設定，也不會寫入 localStorage）
 *     使用者拖曳過面板後，視為已熟悉操作，之後不再隨捲動自動開合（記錄於 localStorage）
 * 面板黏在頂部時，用 --extra-space（面板下方額外保留空間）讓面板佔位高度維持不變，
 * 列表就不會隨動畫 / 拖曳上下移動；使用者的變更在結束後才一次補償捲動位置。
 * ========================================================================= */

import { AppState, GRADIENT_LABELS } from "./state.js";

const COUNT_KEY = "panelCount";
const AUTO_OFF_KEY = "panelAutoOff";

const DRAG_START = 6;          // 拖曳超過此距離（px）才開始拖曳，以下視為點擊
const SCROLL_THRESHOLD = 48;   // 同方向累積捲動超過此距離（px）才自動收合 / 展開
const SCROLL_SETTLE_MS = 250;  // 面板變更後的版面跳動期間忽略捲動事件，避免來回觸發
const ANIM_MS = 260;
// 執行時才查詢（tools/prune-data.mjs 以 jsdom 載入此模組，jsdom 沒有 matchMedia）
const prefersReducedMotion = () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

let rowCount = 0;          // 面板內容總列數
let userCount = null;      // 使用者設定的顯示列數（點擊 / 拖曳）
let shownCount = 0;        // 畫面上實際顯示的列數
let autoCollapsed = false; // 捲動造成的暫時收合
let autoEnabled = true;    // 捲動自動開合；使用者拖曳過後關閉
try {
  const saved = localStorage.getItem(COUNT_KEY);
  if (saved !== null) userCount = Number(saved);
  autoEnabled = localStorage.getItem(AUTO_OFF_KEY) !== "1";
} catch { /* 無法存取 storage 時用預設值 */ }

let lastScrollY = 0;
let scrollAccum = 0;
let ignoreScrollUntil = 0;

let extraSpace = 0;
let transition = null;  // 進行中的拖曳 / 動畫狀態
let animFrame = null;

const getPanel = () => document.querySelector(".global-panel");
const getBody = () => getPanel().querySelector(".panel-body");
const getRows = () => [...getPanel().querySelectorAll(".global-controls > *")];
const effectiveCount = () => (autoCollapsed ? 0 : userCount);

function disableAuto() {
  if (!autoEnabled) return;
  autoEnabled = false;
  try { localStorage.setItem(AUTO_OFF_KEY, "1"); } catch { /* 忽略 */ }
}

/** 面板原本（未黏住時）在頁面中的頂端位置 */
function naturalTop() {
  const wrap = getPanel().parentElement;
  return wrap.getBoundingClientRect().top + window.scrollY + parseFloat(getComputedStyle(wrap).paddingTop);
}

/** 面板是否已黏在頁面頂部（sticky 生效中） */
function isStuck() {
  return window.scrollY > 0 && window.scrollY >= naturalTop();
}

/** 目前篩選條件的精簡摘要，未全開時顯示在切換列上 */
function getFilterSummary() {
  const g = [...AppState.gradientFilter].sort().map(v => GRADIENT_LABELS[v]);
  const s = [...AppState.seasonFilter].sort((a, b) => a - b).map(v => "S" + v);
  return [
    "★" + AppState.globalStars.charStar,
    g.length ? g.join("/") : "全稀有度",
    s.length ? s.join("/") : "全賽季",
  ].join(" · ");
}

/** 更新切換列；count 省略時用目前設定（拖曳中會傳入預覽值） */
export function updatePanelToggle(count = effectiveCount()) {
  const label = count === rowCount ? "全開" : count === 0 ? "收合" : `${count} / ${rowCount}`;
  getPanel().classList.toggle("is-full", count === rowCount);
  document.getElementById("panelStageLabel").textContent = label;
  document.getElementById("panelSummary").textContent = getFilterSummary();
  document.querySelectorAll("#panelStageDots i").forEach((dot, i) => {
    dot.classList.toggle("on", i < count);
  });
}

function showRows(count) {
  shownCount = count;
  getRows().forEach((row, i) => row.classList.toggle("is-hidden", i >= count));
  getPanel().classList.toggle("is-collapsed", count === 0);
}

/** 面板下方額外保留的空間；展開時可為負值（列表暫時鑽到面板底下） */
function setExtraSpace(px) {
  extraSpace = px;
  getPanel().style.setProperty("--extra-space", px + "px");
}

/** 各列數對應的 .panel-body 高度：heights[k] = 顯示前 k 列時的高度（呼叫前 body 高度須已固定） */
function measureHeights() {
  showRows(rowCount);
  const controls = getPanel().querySelector(".global-controls");
  const top = controls.getBoundingClientRect().top;
  const padBottom = parseFloat(getComputedStyle(controls).paddingBottom);
  return [0, ...getRows().map(row =>
    row.getBoundingClientRect().bottom + parseFloat(getComputedStyle(row).marginBottom) - top + padBottom)];
}

/* -------------------------------------------------------------------------
 * 過渡流程：beginTransition → setBodyHeight（拖曳 / 動畫每一幀）→ endTransition
 * 過渡期間所有列都顯示，由 .panel-body 的高度裁切，因此可停在任意高度。
 * ------------------------------------------------------------------------- */
function beginTransition() {
  if (animFrame) { cancelAnimationFrame(animFrame); animFrame = null; }
  if (transition) return transition;

  const panel = getPanel();
  const body = getBody();
  // 量測高度會觸發版面計算，須先關閉 scroll anchoring，否則瀏覽器會自行調整捲動位置
  document.documentElement.style.overflowAnchor = "none";
  const h = body.getBoundingClientRect().height;
  transition = {
    stuck: isStuck(),
    footprint: panel.offsetHeight + extraSpace,  // 黏住時維持不變的佔位高度
  };
  body.style.height = h + "px";
  body.classList.add("is-animating");
  transition.heights = measureHeights();
  return transition;
}

function setBodyHeight(h, extraWhenFree = extraSpace) {
  getBody().style.height = h + "px";
  if (transition.stuck) setExtraSpace(transition.footprint - getPanel().offsetHeight);
  else setExtraSpace(extraWhenFree);
}

function endTransition(count) {
  const panel = getPanel();
  const body = getBody();
  body.style.height = "";
  body.classList.remove("is-animating");
  showRows(count);

  if (transition.stuck && !autoCollapsed) {
    // 使用者的變更：佔位改回實際高度，同時補償捲動位置。
    // 往上可捲的空間不足（補償後面板會脫離黏住）時保留剩餘空間，回到頁面上方時再釋放（見 onScroll）
    const room = Math.max(0, window.scrollY - naturalTop());
    const release = extraSpace > 0 ? Math.min(extraSpace, room) : extraSpace;
    setExtraSpace(extraSpace - release);
    if (release) window.scrollBy(0, -release);
  } else if (!transition.stuck) {
    setExtraSpace(0);
  }
  transition = null;
  requestAnimationFrame(() => { document.documentElement.style.overflowAnchor = ""; });
  ignoreScrollUntil = performance.now() + SCROLL_SETTLE_MS;
  lastScrollY = window.scrollY;
  scrollAccum = 0;
}

/** 以動畫過渡到顯示前 count 列 */
function animateTo(count) {
  const t = beginTransition();
  const startH = parseFloat(getBody().style.height);
  const endH = t.heights[count];
  const startExtra = extraSpace;
  const duration = prefersReducedMotion() || (startH === endH && !startExtra) ? 0 : ANIM_MS;
  ignoreScrollUntil = performance.now() + duration + SCROLL_SETTLE_MS;

  const t0 = performance.now();
  const step = (now) => {
    const p = duration ? Math.min(1, (now - t0) / duration) : 1;
    const eased = 1 - Math.pow(1 - p, 3);  // easeOutCubic
    setBodyHeight(startH + (endH - startH) * eased, startExtra * (1 - eased));
    if (p < 1) animFrame = requestAnimationFrame(step);
    else { animFrame = null; endTransition(count); }
  };
  if (duration) animFrame = requestAnimationFrame(step);
  else step(t0);
}

function setUserCount(count) {
  autoCollapsed = false;
  userCount = Math.min(rowCount, Math.max(0, count));
  try { localStorage.setItem(COUNT_KEY, String(userCount)); } catch { /* 忽略 */ }
  updatePanelToggle();
  animateTo(userCount);
}

function setAutoCollapsed(value) {
  if (autoCollapsed === value) return;
  autoCollapsed = value;
  updatePanelToggle();
  animateTo(effectiveCount());
}

function onScroll() {
  const y = window.scrollY;
  const dy = y - lastScrollY;
  lastScrollY = y;
  if (transition || performance.now() < ignoreScrollUntil) return;

  // 回到頁面上方（面板沒有黏住）時：恢復自動收合，或釋放先前保留的空間
  if (!isStuck()) {
    scrollAccum = 0;
    if (autoEnabled && autoCollapsed) setAutoCollapsed(false);
    else if (extraSpace > 0) animateTo(effectiveCount());
    return;
  }
  if (!autoEnabled) return;

  // 換方向就重新累積，避免小幅抖動觸發
  if (Math.sign(dy) !== Math.sign(scrollAccum)) scrollAccum = 0;
  scrollAccum += dy;

  // 需捲過整個面板高度才收合，避免面板剛黏住頂部就收起
  const canCollapse = y >= naturalTop() + getPanel().offsetHeight;
  if (scrollAccum > SCROLL_THRESHOLD && canCollapse && userCount !== 0) setAutoCollapsed(true);
  else if (scrollAccum < -SCROLL_THRESHOLD) setAutoCollapsed(false);
}

/** 找出最接近高度 h 的列數 */
function nearestCount(heights, h) {
  let best = 0;
  heights.forEach((v, i) => { if (Math.abs(v - h) < Math.abs(heights[best] - h)) best = i; });
  return best;
}

function bindToggle(toggle) {
  let drag = null;       // { y, startH, dragging }
  let dragged = false;   // 拖曳結束後的 click 不當成點擊

  toggle.addEventListener("pointerdown", (e) => {
    drag = { y: e.clientY, startH: null, dragging: false };
    dragged = false;
    toggle.setPointerCapture(e.pointerId);
  });

  toggle.addEventListener("pointermove", (e) => {
    if (!drag) return;
    const dy = e.clientY - drag.y;
    if (!drag.dragging) {
      if (Math.abs(dy) < DRAG_START) return;
      drag.dragging = true;
      dragged = true;
      disableAuto();
      beginTransition();
      drag.startH = parseFloat(getBody().style.height);
      drag.y = e.clientY;  // 從超過門檻的位置開始跟手，避免一開始跳一下
      return;
    }
    const heights = transition.heights;
    const h = Math.min(heights[rowCount], Math.max(0, drag.startH + dy));
    setBodyHeight(h);
    updatePanelToggle(nearestCount(heights, h));
  });

  const end = () => {
    if (drag && drag.dragging && transition) {
      const h = parseFloat(getBody().style.height);
      setUserCount(nearestCount(transition.heights, h));
    }
    drag = null;
  };
  toggle.addEventListener("pointerup", end);
  toggle.addEventListener("pointercancel", end);

  toggle.addEventListener("click", () => {
    if (dragged) { dragged = false; return; }
    setUserCount(effectiveCount() > 0 ? 0 : rowCount);
  });
}

export function bindPanelToggle() {
  rowCount = getRows().length;
  if (userCount === null || !(userCount >= 0 && userCount <= rowCount)) userCount = rowCount;

  const dots = document.getElementById("panelStageDots");
  dots.innerHTML = "<i></i>".repeat(rowCount);

  bindToggle(document.getElementById("panelToggle"));
  lastScrollY = window.scrollY;
  window.addEventListener("scroll", onScroll, { passive: true });
  showRows(effectiveCount());
  updatePanelToggle();
}
